// Generates src/types.ts from the JSON Schema exported by the Python contract
// (`uv run poe contract` -> src/fixtures/schema.json). The generated file is the single
// source of API types for the UI; run `npm run types` after regenerating the contract.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { compile } from "json-schema-to-typescript";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const schema = JSON.parse(readFileSync(resolve(root, "src/fixtures/schema.json"), "utf8"));
// pydantic puts a generated `title` on every field; left in, each field becomes its own alias.
const strip = (node) => {
  if (Array.isArray(node)) return node.map(strip);
  if (node && typeof node === "object") {
    if (Array.isArray(node.prefixItems)) {
      // 2020-12 tuple -> the form json-schema-to-typescript understands.
      const { prefixItems, ...rest } = node;
      return strip({ ...rest, items: prefixItems, additionalItems: false });
    }
    return Object.fromEntries(
      Object.entries(node)
        .filter(([key, value]) => !(key === "title" && typeof value === "string"))
        .map(([key, value]) => [key, strip(value)]),
    );
  }
  return node;
};
const defs = strip(schema.$defs);

// The exported schema only has $defs; compile one root that references all of them so each
// becomes a named, exported type.
const wrapper = {
  title: "Contract",
  type: "object",
  additionalProperties: false,
  properties: Object.fromEntries(Object.keys(defs).map((name) => [name, { $ref: `#/$defs/${name}` }])),
  $defs: defs,
};

const banner = `/* eslint-disable */
// GENERATED by scripts/gen-types.mjs from src/fixtures/schema.json (the pydantic models in
// src/bladesight/contracts.py). Do not edit by hand: run \`npm run types\`.
`;

let ts = await compile(wrapper, "Contract", {
  bannerComment: banner,
  additionalProperties: false,
  declareExternallyReferenced: true,
  unreachableDefinitions: true,
  format: true,
});
// The wrapper interface only exists to pull every definition in; keep the named types.
ts = ts.replace(/export interface Contract \{[\s\S]*?\n\}\n/, "");

// Named aliases for the enums and shapes the UI uses by name; derived, so they cannot drift.
const aliases = `
// --- aliases derived from the types above (added by scripts/gen-types.mjs) ---
export type Verdict = Verification["verdict"];
export type TurbineStatus = Turbine["status"];
export type Trend = Turbine["trend"];
export type DefectType = Assessment["defect_type"];
export type Provider = Assessment["provider"];
export type WorkOrderKind = WorkOrder["kind"];
export type Polygon = Defect["outline"][number];
`;
writeFileSync(resolve(root, "src/types.ts"), ts.trimEnd() + "\n" + aliases);
console.log("wrote src/types.ts");
